const probSig = p => crypto.createHash('sha1').update([p.grade, String(p.q).toLowerCase().replace(/\s+/g, ' ').replace(/[`'‘’ʻʼ]/g, "'"), p.img, p.o.map(v => v.t.toLowerCase() + '#' + v.i).join('|')].join('§')).digest('hex');
