const probNorm = q => String(q || '').toLowerCase().replace(/[`'‘’ʻʼ]/g, "'").replace(/o'/g, 'ö').replace(/g'/g, 'ğ').replace(/[0-9]+([.,][0-9]+)?/g, '#')
