  let pool = all(`SELECT * FROM probs WHERE active=1 AND ${scS}`, ...scA).map(r => ({ ...probRow(r), ns: r.nsig || '' })).filter(p => !ex.includes(p.id) && (topics.length || !PB_LOCKED(p.topic)));
